package com.jollytailor.controller;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/tailor")
public class TailorController {
    private final JdbcTemplate jdbc; private final ObjectMapper mapper;
    public TailorController(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}

    @GetMapping("/customers") public List<Map<String,Object>> customers(@RequestParam(required=false) String q){
        if(q==null||q.isBlank())return jdbc.queryForList("SELECT id,name,phone,address,notes,created_at FROM customers ORDER BY updated_at DESC LIMIT 300");
        String term="%"+q.trim()+"%";return jdbc.queryForList("SELECT id,name,phone,address,notes,created_at FROM customers WHERE name ILIKE ? OR phone ILIKE ? ORDER BY updated_at DESC LIMIT 100",term,term);
    }
    @PostMapping("/customers") @Transactional @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> createCustomer(@RequestBody Map<String,Object>b){String name=text(b,"name"),phone=text(b,"phone");if(name.isBlank()||phone.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Customer name and phone are required");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO customers(id,name,phone,address,notes) VALUES(?,?,?,?,?)",id,name,phone,blank(text(b,"address")),blank(text(b,"notes")));return getCustomer(id);}
    @PatchMapping("/customers/{id}") public Map<String,Object> updateCustomer(@PathVariable UUID id,@RequestBody Map<String,Object>b){String name=text(b,"name"),phone=text(b,"phone");if(name.isBlank()||phone.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Customer name and phone are required");int n=jdbc.update("UPDATE customers SET name=?,phone=?,address=?,notes=?,updated_at=NOW() WHERE id=?",name,phone,blank(text(b,"address")),blank(text(b,"notes")),id);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");return getCustomer(id);}
    @GetMapping("/customers/{id}") public Map<String,Object> customer(@PathVariable UUID id){return getCustomer(id);}
    private Map<String,Object> getCustomer(UUID id){try{return jdbc.queryForMap("SELECT id,name,phone,address,notes,created_at FROM customers WHERE id=?",id);}catch(org.springframework.dao.EmptyResultDataAccessException ex){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");}}

    @GetMapping("/customers/{id}/measurements") public List<Map<String,Object>> measurements(@PathVariable UUID id){return jdbc.queryForList("SELECT id,customer_id,garment_type,unit,dimensions::text AS dimensions,fit_preference,notes,created_at FROM measurements WHERE customer_id=? ORDER BY created_at DESC",id);}
    @PostMapping("/customers/{id}/measurements") @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> addMeasurement(@PathVariable UUID id,@RequestBody Map<String,Object>b,Authentication auth){String garment=text(b,"garmentType"),unit=text(b,"unit");if(garment.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Garment type is required");if(!Set.of("in","cm").contains(unit))unit="in";if(!customerExists(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");Object dims=b.getOrDefault("dimensions",Map.of());String json;try{json=mapper.writeValueAsString(dims);}catch(JsonProcessingException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid measurements");}long userId=currentUserId(auth);UUID mid=UUID.randomUUID();jdbc.update("INSERT INTO measurements(id,customer_id,garment_type,unit,dimensions,fit_preference,notes,created_by) VALUES(?,?,?, ?,?::jsonb,?,?,?)",mid,id,garment,unit,json,blank(text(b,"fitPreference")),blank(text(b,"notes")),userId);return jdbc.queryForMap("SELECT id,customer_id,garment_type,unit,dimensions::text AS dimensions,fit_preference,notes,created_at FROM measurements WHERE id=?",mid);}

    @GetMapping("/orders") public List<Map<String,Object>> orders(@RequestParam(required=false) String q){String sql="SELECT o.id,o.order_number,o.customer_id,o.measurement_id,o.status,o.due_date,o.notes,o.subtotal,o.discount,o.total,o.amount_paid,(o.total-o.amount_paid) AS due,o.created_at,c.name AS customer,c.phone FROM tailoring_orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 300";if(q==null||q.isBlank())return jdbc.queryForList(sql);String term="%"+q.trim()+"%";return jdbc.queryForList("SELECT o.id,o.order_number,o.customer_id,o.measurement_id,o.status,o.due_date,o.notes,o.subtotal,o.discount,o.total,o.amount_paid,(o.total-o.amount_paid) AS due,o.created_at,c.name AS customer,c.phone FROM tailoring_orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_number ILIKE ? OR c.name ILIKE ? OR c.phone ILIKE ? ORDER BY o.created_at DESC LIMIT 100",term,term,term);}
    @GetMapping("/orders/{id}") public Map<String,Object> order(@PathVariable UUID id){Map<String,Object> out;try{out=jdbc.queryForMap("SELECT o.*,c.name AS customer,c.phone,c.address FROM tailoring_orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?",id);}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found");}out.put("items",jdbc.queryForList("SELECT id,product_id,item_name,quantity,unit_rate,amount FROM order_items WHERE order_id=?",id));out.put("payments",jdbc.queryForList("SELECT id,amount,method,reference,note,received_at FROM payments WHERE order_id=? ORDER BY received_at",id));return out;}

    @PostMapping("/orders") @Transactional @ResponseStatus(HttpStatus.CREATED)
    public Map<String,Object> createOrder(@RequestBody Map<String,Object>b,Authentication auth){
        UUID customerId=uuid(b.get("customerId"),"customerId");if(!customerExists(customerId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found");
        UUID measurementId=b.get("measurementId")==null||b.get("measurementId").toString().isBlank()?null:uuid(b.get("measurementId"),"measurementId");
        if(measurementId!=null){Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM measurements WHERE id=? AND customer_id=?",Integer.class,measurementId,customerId);if(count==null||count==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Measurement profile does not belong to this customer");}
        Object raw=b.get("items");if(!(raw instanceof List<?> itemList)||itemList.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"At least one bill item is required");
        UUID id=UUID.randomUUID();String number="JLT-"+java.time.LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,5).toUpperCase();BigDecimal subtotal=BigDecimal.ZERO;List<Map<String,Object>> prepared=new ArrayList<>();
        for(Object item: itemList){if(!(item instanceof Map<?,?> m))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid bill item");String name=String.valueOf(itemValue(m,"name","")).trim();if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Item name is required");int qty;BigDecimal rate;try{qty=Integer.parseInt(String.valueOf(itemValue(m,"quantity",1)));rate=new BigDecimal(String.valueOf(itemValue(m,"rate",0)));}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid quantity or rate");}if(qty<1||rate.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity must be positive and rate cannot be negative");BigDecimal amount=rate.multiply(BigDecimal.valueOf(qty));subtotal=subtotal.add(amount);prepared.add(Map.of("name",name,"quantity",qty,"rate",rate,"amount",amount,"productId",m.get("productId")==null?"":String.valueOf(m.get("productId"))));}
        BigDecimal discount=decimal(b.get("discount"));if(discount.signum()<0||discount.compareTo(subtotal)>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid discount");BigDecimal total=subtotal.subtract(discount);long uid=currentUserId(auth);
        jdbc.update("INSERT INTO tailoring_orders(id,order_number,customer_id,measurement_id,status,due_date,notes,subtotal,discount,total,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,number,customerId,measurementId,"RECEIVED",dateOrNull(b.get("dueDate")),blank(text(b,"notes")),subtotal,discount,total,uid);
        for(Map<String,Object> item:prepared){String productId=String.valueOf(item.get("productId"));jdbc.update("INSERT INTO order_items(id,order_id,product_id,item_name,quantity,unit_rate,amount) VALUES(?,?,?, ?,?,?,?)",UUID.randomUUID(),id,productId.isBlank()?null:UUID.fromString(productId),item.get("name"),item.get("quantity"),item.get("rate"),item.get("amount"));}
        return order(id);
    }
    @PatchMapping("/orders/{id}/status") public Map<String,Object> updateStatus(@PathVariable UUID id,@RequestBody Map<String,Object>b){String status=text(b,"status").toUpperCase();if(!Set.of("RECEIVED","CUTTING","STITCHING","TRIAL","READY","DELIVERED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid order status");int n=jdbc.update("UPDATE tailoring_orders SET status=?,updated_at=NOW() WHERE id=?",status,id);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found");return Map.of("id",id,"status",status);}
    @PostMapping("/orders/{id}/payments") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> recordPayment(@PathVariable UUID id,@RequestBody Map<String,Object>b,Authentication auth){BigDecimal amount=decimal(b.get("amount"));if(amount.signum()<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment must be greater than zero");String method=text(b,"method").toUpperCase();if(!Set.of("CASH","UPI","CARD","BANK_TRANSFER","OTHER").contains(method))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid payment method");Map<String,Object> order;try{order=jdbc.queryForMap("SELECT total,amount_paid FROM tailoring_orders WHERE id=? FOR UPDATE",id);}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found");}BigDecimal total=(BigDecimal)order.get("total"),paid=(BigDecimal)order.get("amount_paid");if(amount.compareTo(total.subtract(paid))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment exceeds outstanding balance");UUID pid=UUID.randomUUID();jdbc.update("INSERT INTO payments(id,order_id,amount,method,reference,note,received_by) VALUES(?,?,?,?,?,?,?)",pid,id,amount,method,blank(text(b,"reference")),blank(text(b,"note")),currentUserId(auth));jdbc.update("UPDATE tailoring_orders SET amount_paid=amount_paid+?,updated_at=NOW() WHERE id=?",amount,id);return jdbc.queryForMap("SELECT id,order_id,amount,method,reference,note,received_at FROM payments WHERE id=?",pid);}

    private Object itemValue(Map<?,?> m,String key,Object fallback){Object value=m.get(key);return value==null?fallback:value;}
    private boolean customerExists(UUID id){Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM customers WHERE id=?",Integer.class,id);return count!=null&&count>0;}
    private long currentUserId(Authentication a){Long id=jdbc.queryForObject("SELECT id FROM app_users WHERE username=?",Long.class,a.getName());return id==null?0:id;}
    private String text(Map<String,Object>b,String k){Object v=b.get(k);return v==null?"":String.valueOf(v).trim();}private String blank(String s){return s.isBlank()?null:s;}
    private BigDecimal decimal(Object o){try{return new BigDecimal(o==null?"0":o.toString());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid numeric value");}}
    private UUID uuid(Object o,String field){try{return UUID.fromString(String.valueOf(o));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid "+field);}}
    private java.sql.Date dateOrNull(Object o){if(o==null||o.toString().isBlank())return null;try{return java.sql.Date.valueOf(LocalDate.parse(o.toString()));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid due date");}}
}
